function greeting(){const hour=Number(new Intl.DateTimeFormat('en',{timeZone:'Asia/Manila',hour:'numeric',hourCycle:'h23'}).format(new Date()));return hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';}
