 const dueTasks=openTasks.filter(t=>t.due<=day()),detail=data.leads.find(l=>l.id===detailId),selectedProperty=data.properties.find(p=>p.id===propertyId),selectedAiLead=data.leads.find(l=>l.id===aiLead)||data.leads[0];
