  {modal==='help'&&<Modal title="Meet your new workspace." subtitle="From first inquiry to the next right step." onClose={()=>setModal(null)}><div className="guide-steps">{[['01','Start with a connection','Add a lead or import your existing Google Sheets CSV. Demo records are fictional and can be edited or deleted.'],['02','Keep the next step visible','Set a follow-up date and create a call, email, or viewing task. Use the Pipeline to track progress.'],['03','Find the right words','Use templates immediately, or connect a Google AI Studio key in Integrations for live AI.'],['04','Review, then send','Save a draft, edit and approve it, then open Gmail. Sending is always your decision.']].map(([n,title,copy])=><div key={n}><span>{n}</span><div><h3>{title}</h3><p>{copy}</p></div></div>)}</div><div className="modal-actions"><button className="button primary" onClick={()=>setModal(null)}>Let’s get started<ArrowRight size={15}/></button></div></Modal>}
  {detail&&<LeadDrawer lead={detail} data={data} busy={saving} thinking={thinking} onClose={()=>setDetailId('')} onEdit={()=>{setEditing(detail);setModal('lead');}} onStage={s=>void changeStage(detail.id,s)} onTask={()=>addTask(detail.id)} onDraft={()=>{setDetailId('');void makeDraft(detail);}} onDelete={()=>setDeleteId(detail.id)} onContact={()=>void mutate(s=>({...s,leads:s.leads.map(l=>l.id===detail.id?{...l,lastContact:day(),stage:l.stage==='New'?'Contacted':l.stage}:l),activities:[activity(detail.id,`${detail.name} marked as contacted`),...s.activities].slice(0,1000)}),'Contact recorded')} onNotes={async notes=>await mutate(s=>({...s,leads:s.leads.map(l=>l.id===detail.id?{...l,notes}:l)}),'Notes saved')} onMatch={()=>{setPropertyLead(detail.id);setDetailId('');go('Properties');}} onTaskToggle={t=>void toggleTask(t)}/>}
